<script setup lang="ts">
import {ref,onMounted,nextTick,computed} from 'vue';
import ReaderTicket from './ReaderTicket.vue';
const props=defineProps<{api:(path:string,method?:string,body?:any)=>Promise<any>,can:(permission:string)=>boolean,isAdmin?:boolean}>();
const directoryOpen=ref(false),directorySource=ref('active_directory'),directoryQuery=ref(''),directoryResults=ref<any[]>([]),directorySearched=ref(false),directoryTruncated=ref(false);
const accounts=ref<any[]|null>(null),accountId=ref<number|null>(null);
async function accountOptions(){await run(async()=>{accounts.value=await props.api('/circulation/accounts');accountId.value=card.value.user_id||null;});}
async function linkAccount(){await run(async()=>{await props.api('/circulation/readers/'+card.value.id+'/account','POST',{request_key:crypto.randomUUID(),user_id:accountId.value});accounts.value=null;notice.value='Учётная запись читателя связана';});}
const sourceLabels:Record<string,string>={active_directory:'Active Directory',platonus:'Platonus','platonus-personal':'Персональные данные Platonus',csv:'CSV',manual:'Вручную',nightly:'Ночное обновление'};
const missingLabels:Record<string,string>={phone:'телефон',email:'email',faculty:'факультет',photo:'фото',iin:'ИИН',birth_date:'дата рождения'};
const runLabels:Record<string,string>={success:'Завершено',error:'Ошибка',dry_run:'Предварительная проверка',running:'Выполняется'};
const problemLabels:Record<string,string>={iin_birth_mismatch:'ИИН не соответствует дате рождения в источнике',duplicate_iin:'ИИН уже связан с другим читателем',invalid_identity:'Некорректный идентификатор',duplicate_source_identity:'Повтор идентификатора в источнике',unconfirmed_cross_source_link:'Связь AD и Platonus не подтверждена',ambiguous_cross_source_link:'Неоднозначная связь AD и Platonus',missing_name:'Не указано ФИО',invalid_personal_or_profile_data:'Проверьте персональные данные и поля карточки'};
const emit=defineEmits<{visit:[code:string],issue:[id:number]}>();
const fields:[string,string,string?][]=[['full_name','ФИО'],['email','Email'],['login','Логин источника'],['phone','Телефон'],['additional_email','Дополнительный email'],['faculty','Факультет'],['department','Кафедра'],['study_group','Группа'],['education_level','Уровень обучения'],['education_program','Программа'],['program_code','Код программы'],['course','Курс','number'],['cohort_year','Год поступления','number'],['position','Должность'],['subdivision','Подразделение'],['valid_until','Билет действителен до','date'],['reregistered_at','Перерегистрация','date']];
const personalFields:[string,string,string?][]=[['iin','ИИН'],['birth_date','Дата рождения','date']];
const filterFields=[['faculty','Факультет'],['department','Кафедра'],['education_program','Программа'],['study_group','Группа'],['course','Курс'],['cohort_year','Год поступления'],['education_level','Уровень обучения']];
const items=ref<any[]>([]),total=ref(0),offset=ref(0),filters=ref<Record<string,string>>({q:'',sort:'full_name',category:'',status:''}),options=ref<any>({categories:{},statuses:{}}),branches=ref<any[]>([]),card=ref<any>(null),stats=ref<any>(null),sync=ref<any>(null),ticket=ref<any>(null),busy=ref(false),error=ref(''),notice=ref(''),advanced=ref(false),editing=ref(false),branchName=ref(''),branchCode=ref('');
const overview=ref<any>(null),cardTab=ref('overview'),columnsOpen=ref(false),exportOpen=ref(false);
const visibleColumns=ref(['ticket','name','category','department','education','status']);
const columnNames:Record<string,string>={ticket:'Билет №',name:'ФИО читателя',category:'Категория читателя',department:'Подразделение',education:'Обучение',status:'Статус'};
const tabs=[['overview','Обзор'],['books','Книги'],['history','История'],['visits','Посещения'],['restrictions','Ограничения'],['data','Данные']];
const loanHistory=ref<any>(null),historyOffset=ref(0);
const identityFields:[string,string][]=[['full_name','ФИО читателя'],['category','Категория читателя'],['birth_date','Дата рождения'],['iin','ИИН'],['gender','Пол'],['status','Статус']];
const studyFields:[string,string][]=[['faculty','Факультет'],['department','Кафедра'],['study_group','Группа'],['education_level','Уровень обучения'],['education_program','Программа'],['course','Курс'],['cohort_year','Год поступления'],['position','Должность']];
const contactFields:[string,string][]=[['email','Адрес электронной почты'],['phone','Номер телефона'],['additional_email','Дополнительная почта']];
const detailGroups=computed(()=>[{name:'Идентификация',fields:identityFields.filter(([key])=>!['iin','birth_date'].includes(key)||props.can('readers.personal_data.view'))},{name:'Учебные данные',fields:studyFields},{name:'Контакты',fields:contactFields}]);
function display(key:string,value:any){if(value===null||value===undefined||value==='')return 'Не заполнено';if(key==='category')return options.value.categories[value]||value;if(key==='status')return options.value.statuses[value]||value;if(key==='gender')return value==='female'?'Женский':value==='male'?'Мужской':'Не указан';if(['birth_date','valid_until','reregistered_at'].includes(key))return String(value).split('-').reverse().join('.');return value;}
const number=(n:number)=>new Intl.NumberFormat('ru-RU').format(n);
async function loadOverview(){const results=await Promise.all(['','&audience=students','&audience=staff','&audience=faculty','&status=blocked','&status=suspended'].map(q=>props.api('/readers?limit=1'+q)));overview.value={total:results[0].total,students:results[1].total,staff:results[2].total,faculty:results[3].total,restricted:results[4].total+results[5].total};}
async function turnPage(delta:number){await run(async()=>{const previous=offset.value;offset.value=Math.max(0,previous+delta);try{await load();}catch(e){offset.value=previous;throw e;}await nextTick();window.scrollTo({top:0,behavior:'instant'});});}
function toggleDirectory(){directoryOpen.value=!directoryOpen.value;window.scrollTo(0,0);}
function back(){card.value=null;ticket.value=null;accounts.value=null;window.scrollTo(0,0);}
async function selectTab(tab:string){cardTab.value=tab;if(tab==='history'&&props.can('circulation.view_any_history'))await run(async()=>{loanHistory.value=await props.api('/circulation/loans?reader_id='+card.value.id+'&offset='+historyOffset.value);});}
async function historyPage(delta:number){historyOffset.value=Math.max(0,historyOffset.value+delta);await selectTab('history');}
function query(){return new URLSearchParams(Object.entries(filters.value).filter(([,v])=>v)).toString();}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){error.value=String(e);}finally{busy.value=false;}}
async function load(){const result=await props.api('/readers?'+query()+'&offset='+offset.value);items.value=result.items;total.value=result.total;}
async function search(){offset.value=0;await run(load);}
async function open(id:number){await run(async()=>{card.value=await props.api('/readers/'+id);editing.value=false;cardTab.value='overview';loanHistory.value=null;historyOffset.value=0;accounts.value=null;ticket.value=null;window.scrollTo(0,0);});}
function create(){cardTab.value='data';window.scrollTo(0,0);card.value={full_name:'',category:'student',status:'active',block_reason:'',branch_ids:[],manual_overrides:[],preferred_branch_id:null,field_owners:{}};editing.value=true;ticket.value=null;}
async function save(){await run(async()=>{const source=card.value;const allowed=['full_name','category','status','block_reason','gender','is_teaching_staff','preferred_branch_id','branch_ids','manual_overrides','version',...fields.map(f=>f[0]),...(props.can('readers.personal_data.view')?personalFields.map(f=>f[0]):[])];const body:any={};for(const key of allowed){if(source[key]!==undefined){body[key]=source[key];if(['iin','birth_date','valid_until','reregistered_at','course','cohort_year'].includes(key)&&body[key]==='')body[key]=null;}}const result=await props.api('/readers'+(source.id?'/'+source.id:''),source.id?'PUT':'POST',body);card.value=await props.api('/readers/'+result.id);editing.value=false;notice.value='Карточка сохранена';await load();await loadOverview();});}
async function uploadPhoto(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>3000000){error.value='Фото должно быть не больше 3 МБ';return;}await run(async()=>{const content=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await props.api('/readers/'+card.value.id+'/photo','POST',{content});card.value.has_photo=true;card.value.photoVersion=Date.now();notice.value='Фото сохранено';});}
async function printTicket(){await run(async()=>{ticket.value=await props.api('/readers/'+card.value.id+'/ticket');});}
async function analytics(){await run(async()=>{stats.value=await props.api('/readers/analytics?'+query());await nextTick();document.getElementById('reader-analytics')?.scrollIntoView({block:'start'});});}
async function resolveConflict(id:number){await run(async()=>{await props.api('/readers/conflicts/'+id+'/resolve','POST');sync.value=await props.api('/readers/sync-status');});}
async function searchDirectory(){await run(async()=>{directoryResults.value=[];directorySearched.value=false;const result=await props.api('/readers/source-search?'+new URLSearchParams({source:directorySource.value,q:directoryQuery.value}));directoryResults.value=result.items;directoryTruncated.value=result.truncated;directorySearched.value=true;});}
async function importDirectory(row:any){await run(async()=>{const result=await props.api('/readers/source-import','POST',{source:row.source,entity_type:row.entity_type,external_id:row.external_id});card.value=await props.api('/readers/'+result.id);editing.value=false;directoryOpen.value=false;notice.value=result.warning||'Читатель загружен. Билет и история сохранены.';await load();await loadOverview();cardTab.value='overview';loanHistory.value=null;historyOffset.value=0;window.scrollTo(0,0);});}
async function synchronization(){await run(async()=>{sync.value=await props.api('/readers/sync-status');await nextTick();document.getElementById('reader-sync')?.scrollIntoView({block:'start'});});}
async function exportFile(format:string){await run(async()=>{const response=await fetch('/api/readers/export?'+query()+'&format='+format,{credentials:'same-origin'});if(!response.ok)throw Error('Выгрузка недоступна: '+response.status);const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download='readers.'+format;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
async function saveBranch(b:any){await run(async()=>{await props.api('/reader-branches/'+b.id,'PUT',{code:b.code,name:b.name,active:b.active,position:b.position});notice.value='Пункт обслуживания сохранён';});}
async function addBranch(){await run(async()=>{await props.api('/reader-branches','POST',{code:branchCode.value,name:branchName.value});branches.value=await props.api('/reader-branches');branchCode.value='';branchName.value='';});}
function runCount(r:any,key:string){return r.source==='nightly'?Object.values(r.counts).reduce((sum:number,c:any)=>sum+Number(c?.[key]||0),0):Number(r.counts[key]||0);}
function dateTime(v:string){return v?new Date(v.endsWith('Z')||/[+-]\d\d:\d\d$/.test(v)?v:v+'Z').toLocaleString('ru-RU',{timeZone:'Asia/Almaty'}):'—';}
onMounted(()=>run(async()=>{[options.value,branches.value]=await Promise.all([props.api('/readers/options'),props.api('/reader-branches')]);await Promise.all([load(),loadOverview()]);}));
defineExpose({open});
</script>
<template>
<section class="readers-page">
<div class="page-heading reader-page-heading"><div><h1>{{card?(card.full_name||'Новый читатель'):'Читатели'}}</h1><p>{{card?(card.faculty||'Карточка читателя'):'Единая база читателей университета: билеты, учебные данные, книговыдача.'}}</p></div>
<div class="reader-actions" v-if="!card"><button v-if="can('readers.analytics.view')" :disabled="busy" @click="analytics">↗ Аналитика</button><button v-if="can('readers.registry.edit')" @click="create">＋ Зарегистрировать</button><div class="reader-menu" v-if="can('readers.registry.export')"><button class="primary" :aria-expanded="exportOpen" @click="exportOpen=!exportOpen">↓ Выгрузить</button><div v-if="exportOpen" class="reader-menu-panel"><button :disabled="busy" @click="exportFile('xlsx');exportOpen=false">Excel (.xlsx)</button><button :disabled="busy" @click="exportFile('csv');exportOpen=false">CSV</button></div></div></div>
<div class="reader-actions" v-else><button @click="back">← К реестру</button><button v-if="card.id&&can('readers.ticket.print')" :disabled="busy" @click="printTicket">▣ Печать билета</button><button v-if="card.id&&can('circulation.issue')" class="primary" @click="emit('issue',card.id)">⇄ Выдать книгу</button></div></div>
<section v-if="directoryOpen" class="card" aria-label="Поиск в источниках">
<h2>Загрузить читателя из AD / Platonus</h2><p>Введите ФИО или логин. Выберите человека и загрузите актуальную карточку.</p>
<form class="toolbar" @submit.prevent="searchDirectory"><label>Источник<select v-model="directorySource" @change="directoryResults=[];directorySearched=false"><option value="active_directory">Active Directory</option><option value="platonus">Platonus</option></select></label><label>ФИО или логин<input v-model="directoryQuery" minlength="3" maxlength="100" required></label><button :disabled="busy">{{busy?'Подождите…':'Найти'}}</button><button type="button" @click="directoryOpen=false">Закрыть</button></form>
<p v-if="directorySearched&&!directoryResults.length">Читатель не найден. Проверьте написание или выберите другой источник.</p><p v-if="directoryTruncated">Найдено больше 20 человек. Уточните ФИО или логин.</p>
<table v-if="directoryResults.length"><thead><tr><th>ФИО</th><th>Логин</th><th>Группа / подразделение</th><th></th></tr></thead><tbody><tr v-for="r in directoryResults" :key="r.entity_type+':'+r.external_id"><td>{{r.full_name}}</td><td>{{r.login}}</td><td>{{r.study_group||r.department}}</td><td><button :disabled="busy" @click="importDirectory(r)">{{r.reader_id?'Обновить карточку':'Загрузить читателя'}}</button></td></tr></tbody></table>
</section>
<p v-if="error" role="alert" class="error">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
<template v-if="card">
<div class="reader-hero" v-if="card.id"><img v-if="card.has_photo" :src="'/api/readers/'+card.id+'/photo?v='+(card.photoVersion||0)" alt="Фото читателя"><div v-else class="reader-avatar">{{card.full_name?.charAt(0)}}</div><div class="reader-hero-text"><span class="reader-eyebrow">БИЛЕТ №</span><h2>{{card.ticket_number}}</h2><p class="reader-code">Штрихкод: {{card.barcode}}</p><p>{{options.categories[card.category]}}</p></div><span class="reader-status" :class="card.status">{{options.statuses[card.status]}}</span></div>
<nav v-if="card.id" class="reader-tabs" aria-label="Разделы карточки"><button v-for="[key,label] in tabs" :key="key" :class="{selected:cardTab===key}" :aria-current="cardTab===key?'page':undefined" @click="editing=false;selectTab(key)">{{label}}</button></nav>
<div v-if="cardTab==='data'||editing" class="card reader-edit-panel">
<div class="reader-actions"><button v-if="card.id&&can('readers.registry.edit')" @click="editing?open(card.id):editing=true">{{editing?'Отменить изменения':'Редактировать данные'}}</button><button v-if="isAdmin&&card.id" @click="accountOptions">Связать вход читателя</button></div>
<label v-if="card.id&&can('readers.registry.edit')">Добавить / заменить фото<input type="file" accept="image/jpeg,image/png" @change="uploadPhoto"></label>
<form v-if="accounts" @submit.prevent="linkAccount"><p>Выберите учётную запись с ролью «Читатель».</p><select v-model="accountId" aria-label="Учётная запись читателя"><option :value="null">Не связана</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{a.name}} · {{a.login}}</option></select><button :disabled="busy">Сохранить связь</button><button type="button" @click="accounts=null">Отмена</button></form>
<form v-if="editing" @submit.prevent="save" class="reader-form">
<label>Категория<select v-model="card.category"><option v-for="(label,key) in options.categories" :value="key">{{label}}</option></select></label>
<label>Статус<select v-model="card.status"><option v-for="(label,key) in options.statuses" :value="key">{{label}}</option></select></label><label>Причина блокировки<input v-model="card.block_reason" maxlength="1000"></label>
<div v-for="[key,label,type] in [...fields,...(can('readers.personal_data.view')?personalFields:[])]" :key="key"><label :for="'reader-'+key">{{label}}</label><small v-if="card.field_owners?.[key]">Источник: {{card.field_owners[key]}} <label><input type="checkbox" :value="key" v-model="card.manual_overrides"> Ручное переопределение</label></small><input :id="'reader-'+key" v-model="card[key]" :type="type||'text'" :required="key==='full_name'" :disabled="!!card.field_owners?.[key]&&!card.manual_overrides.includes(key)"></div>
<label>Пол<select v-model="card.gender"><option value="">Не указан</option><option value="male">Мужской</option><option value="female">Женский</option></select></label>
<label>Основной пункт<select v-model="card.preferred_branch_id"><option :value="null">Не выбран</option><option v-for="b in branches" :value="b.id">{{b.name}}</option></select></label>
<fieldset><legend>Пункты обслуживания</legend><label v-for="b in branches"><input type="checkbox" :value="b.id" v-model="card.branch_ids">{{b.name}}</label></fieldset><button class="primary" :disabled="busy">Сохранить</button>
</form>
</div>
<template v-if="!editing">
<div v-if="card.status!=='active'" class="reader-banner warning">Обслуживание приостановлено: {{card.block_reason||options.statuses[card.status]}}</div>
<div v-else-if="cardTab==='overview'" class="reader-banner">✓ Читатель активен. Ограничения и доступность экземпляра проверяются при выдаче.</div>
<div class="reader-profile-grid">
<div class="reader-profile-main">
<template v-if="['overview','data'].includes(cardTab)"><section v-for="group in detailGroups" :key="group.name" class="card reader-info"><h2>{{group.name}}</h2><dl><div v-for="[key,label] in group.fields" :key="key"><dt>{{label}}</dt><dd :class="{muted:!card[key]}">{{display(key,card[key])}}</dd></div></dl></section></template>
<section v-if="['overview','books'].includes(cardTab)" class="card reader-info"><h2>Сейчас на руках <span>{{card.circulation?.used??'—'}}</span></h2><template v-if="card.circulation"><p v-if="!card.circulation.loans.length" class="muted">Книг на руках нет.</p><div v-for="loan in card.circulation.loans" :key="loan.id" class="reader-loan"><strong>{{loan.title}}</strong><p>Инв. {{loan.inventory_number}} · Вернуть до {{dateTime(loan.due_at)}}</p></div><p class="muted">Лимит выдачи: {{card.circulation.max_loans}} · Просрочено: {{card.circulation.overdue}}</p></template><p v-else class="muted">Для просмотра выдач необходимы права доступа к книговыдаче.</p></section>
<section v-if="['overview','restrictions'].includes(cardTab)" class="card reader-info"><h2>Задолженности и инциденты</h2><template v-if="card.circulation"><p v-if="!card.circulation.fines.length&&!card.circulation.incidents.length" class="muted">Неоплаченных штрафов и открытых инцидентов нет.</p><p v-for="fine in card.circulation.fines" :key="fine.id">Штраф №{{fine.id}}: {{fine.amount}} ₸ · {{fine.reason||'Без примечания'}}</p><p v-for="incident in card.circulation.incidents" :key="incident.id">Инцидент №{{incident.id}} · {{incident.notes||'Открыт'}}</p></template><p v-else class="muted">Данные о задолженностях недоступны с вашими правами.</p><p v-if="card.block_reason">Причина ограничения: {{card.block_reason}}</p><p v-if="card.problems?.length" class="error">Данные требуют проверки: {{card.problems.map((p:string)=>problemLabels[p]||p).join(', ')}}</p></section>
<section v-if="cardTab==='history'" class="card reader-info"><h2>История выдач</h2><template v-if="can('circulation.view_any_history')"><p v-if="!loanHistory">{{busy?'Загружаем историю…':'История не загружена.'}}</p><template v-else><p class="muted">Всего выдач: {{loanHistory.total}}</p><p v-if="!loanHistory.items.length">Выдач ещё не было.</p><div v-for="loan in loanHistory.items" :key="loan.id" class="reader-loan"><strong>{{loan.title}}</strong><p>Инв. {{loan.inventory_number}} · {{({active:'На руках',returned:'Возвращена',lost:'Утрачена'} as any)[loan.status]||loan.status}}</p><small>Выдана: {{dateTime(loan.issued_at)}} · Возврат: {{dateTime(loan.closed_at)}}</small></div><div class="reader-actions"><button :disabled="busy||historyOffset===0" @click="historyPage(-50)">Назад</button><button :disabled="busy||historyOffset+50>=loanHistory.total" @click="historyPage(50)">Далее</button></div></template></template><p v-else>Нет прав на просмотр полной истории выдач.</p></section>
<section v-if="cardTab==='visits'" class="card reader-info"><h2>Посещения библиотеки</h2><p>Всего: {{card.visits_count}}</p><p v-if="!card.visits?.length" class="muted">Посещений ещё не было.</p><p v-else class="muted">Последние {{card.visits.length}} посещений</p><div v-for="visit in card.visits" :key="visit.id" class="reader-loan">{{dateTime(visit.scanned_at)}} · {{branches.find(b=>b.id===visit.branch_id)?.name||'Пункт не указан'}}</div></section>
<section v-if="['overview','data'].includes(cardTab)" class="card reader-info"><h2>Обслуживание</h2><p class="reader-eyebrow">ПУНКТЫ ОБСЛУЖИВАНИЯ</p><div class="reader-actions"><span v-for="branch in branches.filter(b=>card.branch_ids?.includes(b.id))" :key="branch.id" class="reader-branch" :class="{preferred:branch.id===card.preferred_branch_id}">{{branch.id===card.preferred_branch_id?'★ ':''}}{{branch.name}}</span><span v-if="!card.branch_ids?.length" class="muted">Не назначены</span></div><p>Билет действителен до: {{display('valid_until',card.valid_until)}}</p><p>Перерегистрация: {{display('reregistered_at',card.reregistered_at)}}</p></section>
</div>
<aside class="reader-profile-side"><section class="card reader-info"><h2>Посещения библиотеки</h2><dl class="reader-side-facts"><div><dt>Всего посещений</dt><dd>{{card.visits_count||0}}</dd></div><div><dt>Последнее посещение</dt><dd>{{dateTime(card.last_visit)}}</dd></div><div><dt>Входы на сайт</dt><dd>{{card.website_logins===null?'Вход не связан':card.website_logins}}</dd></div></dl><button v-if="can('visits.record')" @click="emit('visit',card.barcode)">Зарегистрировать посещение</button></section><section class="card reader-info"><h2>Источник данных</h2><p v-for="identity in card.identities" :key="identity.source+identity.external_id">{{sourceLabels[identity.source]||identity.source}}<small class="reader-identity">{{identity.external_id}}</small></p><dl class="reader-side-facts"><div><dt>Логин</dt><dd>{{card.login||'Не заполнено'}}</dd></div><div><dt>Синхронизировано</dt><dd>{{dateTime(card.last_synced_at)}}</dd></div></dl></section><section class="card reader-info"><h2>Обходной лист</h2><p class="muted">Оформление обходного листа пока недоступно.</p></section></aside>
</div>
</template>
<ReaderTicket v-if="ticket" :ticket="ticket" @close="ticket=null" />
</template>
<template v-else>
<div class="reader-metrics" v-if="overview"><div v-for="[key,label] in [['total','Читателей'],['students','Обучающихся'],['staff','Сотрудников'],['faculty','ППС']]" :key="key" class="card"><span>{{label}}</span><strong>{{number(overview[key])}}</strong></div></div>
<p v-if="overview" class="reader-restricted"><strong>{{number(overview.restricted)}}</strong> С ограничениями по статусу</p>
<form class="reader-search" @submit.prevent="search"><div class="reader-filter-row"><input aria-label="Поиск читателя" v-model="filters.q" placeholder="ФИО, билет, штрихкод, почта, телефон, логин"><select v-model="filters.category" aria-label="Тип читателя"><option value="">Тип читателя</option><option v-for="(label,key) in options.categories" :value="key">{{label}}</option></select><select v-model="filters.status" aria-label="Статус читателя"><option value="">Статус</option><option v-for="(label,key) in options.statuses" :value="key">{{label}}</option></select><input v-model="filters.faculty" aria-label="Факультет" placeholder="Факультет"><input v-model="filters.course" aria-label="Курс" placeholder="Курс" type="number" min="1" max="20"><button type="button" :aria-expanded="advanced" @click="advanced=!advanced">☷ Фильтры</button><button class="primary" :disabled="busy">Применить</button></div><div v-if="advanced" class="reader-form card">
<label>Аудитория<select v-model="filters.audience"><option value="">Все</option><option value="students">Обучающиеся</option><option value="faculty">ППС</option><option value="staff">Сотрудники</option></select></label>
<label>Категория<select v-model="filters.category"><option value="">Все</option><option v-for="(label,key) in options.categories" :value="key">{{label}}</option></select></label><label>Статус<select v-model="filters.status"><option value="">Все</option><option v-for="(label,key) in options.statuses" :value="key">{{label}}</option></select></label>
<label v-for="[key,label] in filterFields">{{label}}<input v-model="filters[key]"></label><label>Пол<select v-model="filters.gender"><option value="">Любой</option><option value="male">Мужской</option><option value="female">Женский</option></select></label><label>Пункт<select v-model="filters.branch_id"><option value="">Все</option><option v-for="b in branches" :value="String(b.id)">{{b.name}}</option></select></label>
<label>Зарегистрирован с<input type="date" v-model="filters.registered_from"></label><label>По<input type="date" v-model="filters.registered_to"></label><label>Источник<select v-model="filters.source"><option value="">Любой</option><option value="platonus">Platonus</option><option value="active_directory">AD</option></select></label><label>Наличие в источнике<select v-model="filters.source_presence"><option value="">Есть связь</option><option value="absent">Нет связи</option></select></label>
<label>Не заполнено<select v-model="filters.missing"><option value="">Не фильтровать</option><option v-for="f in ['phone','email','faculty','photo',...(can('readers.personal_data.view')?['iin','birth_date']:[])]" :value="f">{{({phone:'Телефон',email:'Email',faculty:'Факультет',photo:'Фото',iin:'ИИН',birth_date:'Дата рождения'} as any)[f]}}</option></select></label><label>Конфликты<select v-model="filters.conflicts"><option value="">Все</option><option value="true">Требуют проверки</option></select></label><label v-if="can('readers.personal_data.view')">Несовпадение ИИН и даты рождения<select v-model="filters.iin_mismatch"><option value="">Все</option><option value="true">Требуют проверки</option></select></label><label>Входы на сайт<select v-model="filters.login_activity"><option value="">Все</option><option value="yes">Есть входы</option><option value="no">Нет подтверждённых входов</option></select></label><label>Сортировка<select v-model="filters.sort"><option value="full_name">ФИО</option><option value="-registered_at">Новые сначала</option><option value="ticket_number">Номер билета</option><option value="status">Статус</option></select></label></div></form>
<div class="reader-list-tools"><span><strong>{{number(total)}}</strong> читателей в выборке</span><div class="reader-actions"><button @click="columnsOpen=!columnsOpen" :aria-expanded="columnsOpen">Настроить колонки</button><button v-if="can('readers.source.import')" @click="toggleDirectory()">Найти в AD / Platonus</button><button v-if="can('readers.sync.admin')" :disabled="busy" @click="synchronization">Синхронизация</button><button v-if="Object.entries(filters).some(([k,v])=>k!=='sort'&&v)" :disabled="busy" @click="filters={q:'',sort:'full_name',category:'',status:''};search()">Сбросить фильтры</button></div></div>
<div v-if="columnsOpen" class="reader-column-settings"><label v-for="(label,key) in columnNames" :key="key"><input type="checkbox" v-model="visibleColumns" :value="key" :disabled="key==='name'"> {{label}}</label></div>
<div class="card reader-table"><div class="reader-table-scroll"><table><thead><tr><template v-for="(label,key) in columnNames" :key="key"><th v-if="visibleColumns.includes(key)">{{label}}</th></template></tr></thead><tbody><tr v-for="r in items" :key="r.id"><td v-if="visibleColumns.includes('ticket')"><button class="reader-ticket-link" @click="open(r.id)">{{r.ticket_number}}</button><small class="reader-code">{{r.barcode}}</small></td><td v-if="visibleColumns.includes('name')"><button class="reader-name-link" @click="open(r.id)">{{r.full_name}}</button><small>{{r.email||'Электронная почта отсутствует'}}</small></td><td v-if="visibleColumns.includes('category')">{{options.categories[r.category]}} <span v-if="r.is_teaching_staff" class="reader-faculty-badge">ППС</span></td><td v-if="visibleColumns.includes('department')">{{r.faculty||r.subdivision||'—'}}<small>{{r.department}}</small></td><td v-if="visibleColumns.includes('education')">{{r.study_group||r.position||r.education_level||'—'}}<small v-if="r.course">{{r.course}} курс</small></td><td v-if="visibleColumns.includes('status')"><span class="reader-status" :class="r.status">{{options.statuses[r.status]}}</span></td></tr><tr v-if="!items.length"><td :colspan="visibleColumns.length" class="reader-empty">Читатели не найдены. Измените условия поиска.</td></tr></tbody></table></div><div class="reader-pagination"><span>{{total?offset+1:0}}–{{Math.min(offset+50,total)}} из {{number(total)}}</span><div class="reader-actions"><button :disabled="offset===0||busy" @click="turnPage(-50)">← Назад</button><button :disabled="offset+50>=total||busy" @click="turnPage(50)">Далее →</button></div></div></div>
<div v-if="stats" id="reader-analytics" class="card"><h2>Аналитика текущей выборки</h2><p>Читателей: {{stats.total}}</p><div class="reader-form"><div v-for="key in ['category','faculty','course','status','branches']"><h3>{{({category:'Категория',faculty:'Факультет',course:'Курс',status:'Статус',branches:'Пункты'} as any)[key]}}</h3><p v-for="row in stats[key]">{{options.categories[row.label]||options.statuses[row.label]||row.label}}: {{row.count}}</p></div></div><p>Не заполнено: <span v-for="(n,key) in stats.missing">{{missingLabels[String(key)]||key}} — {{n}}; </span></p><h3>Регистрации за 12 месяцев (текущая выборка)</h3><p v-for="r in stats.registrations">{{r.month}}: {{r.count}}</p><p>Активность с {{stats.activity_period.from}} по {{stats.activity_period.to}}: посещений {{stats.physical_visits_30_days}}, входов на сайт {{stats.website_logins_30_days}}.</p><p>{{stats.website_logins}}</p></div>
<div v-if="sync" id="reader-sync" class="card"><h2>Синхронизация</h2><p>AD: {{sync.ad_enabled?'включён':'отключён'}} · Platonus: {{sync.platonus_enabled?'включён':'отключён'}}</p><p v-if="!sync.status_mapping_confirmed">Соответствия статусов Platonus не подтверждены. Автоматическое приостановление запрещено.</p><p>Читатели загружаются из Active Directory и Platonus: сначала AD, затем недостающие люди из Platonus, затем ИИН и даты рождения студентов. Повторная загрузка обновляет карточки и сохраняет номера билетов.</p><p>Ночное обновление: {{sync.nightly_enabled?'каждый день в '+sync.nightly_time+' (Алматы) при работающем сервисе расписания':'не настроено'}}. Реестр и посещения работают с уже загруженными данными даже при недоступности источников.</p><p v-for="(r,source) in sync.last_success">{{sourceLabels[String(source)]||source}} — последний успешный запуск: {{r?dateTime((r as any).ended_at):'ещё не было'}}</p><p v-if="!sync.runs.length">Запусков ещё не было.</p><div v-for="r in sync.runs"><strong>{{sourceLabels[r.source]||r.source}} · {{runLabels[r.status]||r.status}} · {{dateTime(r.started_at)}}</strong><p>Прочитано: {{runCount(r,'read')}} · Создано: {{runCount(r,'created')}} · Обновлено: {{runCount(r,'updated')}} · Приостановлено: {{runCount(r,'suspended')}} · Ошибок: {{runCount(r,'errors')}}</p><p>{{r.message}}</p></div><h3>Требуют проверки</h3><p v-for="c in sync.conflicts">{{c.source}} / {{c.entity_type}} / {{c.external_id}}: {{problemLabels[c.code]||c.code}} <button :disabled="busy" @click="resolveConflict(c.id)">Проверено</button></p></div>
<details v-if="can('readers.registry.edit')" class="card"><summary>Пункты обслуживания</summary><div class="toolbar" v-for="b in branches"><span>{{b.code}}</span><input aria-label="Название существующего пункта" v-model="b.name"><label><input type="checkbox" v-model="b.active"> Активен</label><button @click="saveBranch(b)">Сохранить пункт</button></div><form class="toolbar" @submit.prevent="addBranch"><input v-model="branchCode" placeholder="Код, например MAIN" required><input v-model="branchName" placeholder="Название пункта" required><button :disabled="busy">Добавить пункт</button></form></details>
</template>
</section>
</template>
